51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	};
57	
58	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
59	// separate term rather than folded into a `base * 1.1` factor, which is not
60	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
61	const quotePremium = (items: Item[]): number => {
62	  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
63	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
64	};
65	
66	const quote = (step: QuoteStep): QuoteResult => ({
67	  premium: quotePremium(step.items),
68	});
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => ({
71	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
72	});
