const quote = (step: QuoteStep): QuoteResult => ({
  premium: quotePremium(step.items),
});

const runStep = (step: Step): Result => {
  switch (step.op) {
    case "quote":
      return quote(step);
    default:
      throw new Error(`unsupported step: ${step.op}`);
  }
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

